export interface PokemonStats {
  hp: number;
  attack: number;
  defense: number;
  specialAttack: number;
  specialDefense: number;
  speed: number;
}

export interface PokemonImage {
  /** Path relative to the app's base URL, e.g. "assets/pokemon/ab12….png". */
  path: string;
  width: number;
  height: number;
  hasAlpha: boolean;
}

/** One record of public/data/pokemon.json (generated by tools/process_assets.py). */
export interface Pokemon {
  id: number;
  name: string;
  slug: string;
  genus: string | null;
  generation: number;
  types: string[];
  stats: PokemonStats;
  baseStatTotal: number;
  heightM: number | null;
  weightKg: number | null;
  baseExperience: number | null;
  captureRate: number | null;
  baseHappiness: number | null;
  isBaby: boolean | null;
  isLegendary: boolean | null;
  isMythical: boolean | null;
  image: PokemonImage;
}

export interface PokemonDataset {
  schemaVersion: number;
  count: number;
  types: string[];
  generations: number[];
  pokemon: Pokemon[];
}
